const nextClaimCandidate = `-- name: NextClaimCandidate :one
SELECT t.id, t.project, t.kind, t.title, t.body, t.status, t.resolution, t.priority, t.pool, t.holder, t.lease_until, t.fence, t.parent_id, t.defer_until, t.ephemeral, t.fields, t.meta, t.revision, t.created_by, t.created_at, t.updated_at, t.closed_at, t.f_key, t.f_to, t.f_state, t.f_workflow, t.f_index, t.f_waiting FROM tickets t
WHERE t.project = ?
  AND t.kind IN (/*SLICE:kinds*/?)
  AND (
    (t.status = 'in_progress' AND t.holder = ?)
    OR (t.status = 'open' AND t.holder = ?)
    OR (t.status = 'open' AND t.holder = '' AND t.pool = ?)
  )
  AND t.defer_until <= ?
  -- fields.wait parks a ticket until the controller clears it (#381).
  AND t.f_waiting = 0
  AND NOT EXISTS (
    SELECT 1 FROM edges e JOIN tickets b ON b.id = e.to_id
    WHERE e.from_id = t.id AND e.kind IN ('blocks','waits_for')
      -- A step unblocks the next only when it closed done or skipped (#90, #385).
      AND (b.status <> 'closed' OR (b.kind = 'step' AND b.resolution NOT IN ('done','skipped'))))
  -- Resource slots, as in ReadyTickets (#400). My own in-progress
  -- ticket already holds its slots: h.id <> t.id leaves it out.
  AND NOT EXISTS (
    SELECT 1 FROM ticket_resources r
    JOIN resource_caps c ON c.name = r.rkey OR c.name = r.rname
    WHERE r.ticket_id = t.id AND c.capacity <= (
      SELECT count(*) FROM ticket_resources hr JOIN tickets h ON h.id = hr.ticket_id
      WHERE h.status = 'in_progress' AND h.id <> t.id AND hr.rkey = r.rkey))
  -- Provider slots (#407); my in-progress ticket already holds its slot.
  AND (t.status = 'in_progress' OR NOT EXISTS (
    SELECT 1 FROM ticket_resources r
    JOIN resource_providers p ON p.name = r.rkey
    WHERE r.ticket_id = t.id
      AND NOT EXISTS (SELECT 1 FROM resource_slots s WHERE s.pool = p.name AND s.state = 'ready')))
ORDER BY
  CASE WHEN t.status = 'in_progress' THEN 0
       WHEN t.holder <> '' THEN 1 -- open with a holder can only be mine here
       ELSE 2 END,
  t.priority, t.created_at, t.id
LIMIT 1
`

type NextClaimCandidateParams struct {
	Project    string
	Kinds      []string
	Holder     string
	Holder_2   string
	Pool       string
	DeferUntil int64
}

// Three tiers: my in-progress work, tickets pre-assigned to me, the pool queue.
func (q *Queries) NextClaimCandidate(ctx context.Context, arg NextClaimCandidateParams) (Ticket, error) {
	query := nextClaimCandidate
	var queryParams []interface{}
	queryParams = append(queryParams, arg.Project)
	if len(arg.Kinds) > 0 {
		for _, v := range arg.Kinds {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:kinds*/?", strings.Repeat(",?", len(arg.Kinds))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:kinds*/?", "NULL", 1)
	}
	queryParams = append(queryParams, arg.Holder)
	queryParams = append(queryParams, arg.Holder_2)
	queryParams = append(queryParams, arg.Pool)
	queryParams = append(queryParams, arg.DeferUntil)
	row := q.db.QueryRowContext(ctx, query, queryParams...)
	var i Ticket
	err := row.Scan(
		&i.ID,
		&i.Project,
		&i.Kind,
		&i.Title,
		&i.Body,
		&i.Status,
		&i.Resolution,
		&i.Priority,
		&i.Pool,
		&i.Holder,
		&i.LeaseUntil,
		&i.Fence,
		&i.ParentID,
		&i.DeferUntil,
		&i.Ephemeral,
		&i.Fields,
		&i.Meta,
		&i.Revision,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ClosedAt,
		&i.FKey,
		&i.FTo,
		&i.FState,
		&i.FWorkflow,
		&i.FIndex,
		&i.FWaiting,
	)
	return i, err
}

const orphanedTickets = `-- name: OrphanedTickets :many
SELECT t.id, t.project, t.kind, t.title, t.body, t.status, t.resolution, t.priority, t.pool, t.holder, t.lease_until, t.fence, t.parent_id, t.defer_until, t.ephemeral, t.fields, t.meta, t.revision, t.created_by, t.created_at, t.updated_at, t.closed_at, t.f_key, t.f_to, t.f_state, t.f_workflow, t.f_index, t.f_waiting FROM tickets t
WHERE (? = 1 OR t.project = ?)
  AND t.status = 'open'
  AND t.holder = ''
  AND t.kind IN (/*SLICE:kinds*/?)
  AND (t.pool = '' OR t.pool NOT IN (/*SLICE:known*/?))
ORDER BY t.priority, t.created_at, t.id
LIMIT CAST(? AS INTEGER)
`

type OrphanedTicketsParams struct {
	Column1 interface{}
	Project string
	Kinds   []string
	Known   []string
	Column5 int64
}

// OrphanedTickets is open, unclaimed claimable work no pool will pick up:
// no pool, or a pool name not in known (the loaded config).
// Parameters after a sqlc.slice are bare ?: sqlc numbers named ones ?N
// from the unexpanded query, so they would point into the list.
func (q *Queries) OrphanedTickets(ctx context.Context, arg OrphanedTicketsParams) ([]Ticket, error) {
	query := orphanedTickets
	var queryParams []interface{}
	queryParams = append(queryParams, arg.Column1)
	queryParams = append(queryParams, arg.Project)
	if len(arg.Kinds) > 0 {
		for _, v := range arg.Kinds {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:kinds*/?", strings.Repeat(",?", len(arg.Kinds))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:kinds*/?", "NULL", 1)
	}
	if len(arg.Known) > 0 {
		for _, v := range arg.Known {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:known*/?", strings.Repeat(",?", len(arg.Known))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:known*/?", "NULL", 1)
	}
	queryParams = append(queryParams, arg.Column5)
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Ticket{}
	for rows.Next() {
		var i Ticket
		if err := rows.Scan(
			&i.ID,
			&i.Project,
			&i.Kind,
			&i.Title,
			&i.Body,
			&i.Status,
			&i.Resolution,
			&i.Priority,
			&i.Pool,
			&i.Holder,
			&i.LeaseUntil,
			&i.Fence,
			&i.ParentID,
			&i.DeferUntil,
			&i.Ephemeral,
			&i.Fields,
			&i.Meta,
			&i.Revision,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ClosedAt,
			&i.FKey,
			&i.FTo,
			&i.FState,
			&i.FWorkflow,
			&i.FIndex,
			&i.FWaiting,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const readyTickets = `-- name: ReadyTickets :many
SELECT t.id, t.project, t.kind, t.title, t.body, t.status, t.resolution, t.priority, t.pool, t.holder, t.lease_until, t.fence, t.parent_id, t.defer_until, t.ephemeral, t.fields, t.meta, t.revision, t.created_by, t.created_at, t.updated_at, t.closed_at, t.f_key, t.f_to, t.f_state, t.f_workflow, t.f_index, t.f_waiting FROM tickets t
WHERE t.project = ?
  AND t.status = 'open'
  AND t.kind IN (/*SLICE:kinds*/?)
  AND (? = 1 OR t.pool = ?)
  AND t.defer_until <= ?
  -- fields.wait parks a ticket until the controller clears it (#381).
  AND t.f_waiting = 0
  AND NOT EXISTS (
    SELECT 1 FROM edges e JOIN tickets b ON b.id = e.to_id
    WHERE e.from_id = t.id AND e.kind IN ('blocks','waits_for')
      -- A step unblocks the next only when it closed done or skipped (#90, #385).
      AND (b.status <> 'closed' OR (b.kind = 'step' AND b.resolution NOT IN ('done','skipped'))))
  -- Every resource the ticket needs has a free slot (#400). Occupancy
  -- is in-progress tickets naming the same key; a key "name:..." takes
  -- the cap of "name"; a key with no cap is unlimited.
  AND NOT EXISTS (
    SELECT 1 FROM ticket_resources r
    JOIN resource_caps c ON c.name = r.rkey OR c.name = r.rname
    WHERE r.ticket_id = t.id AND c.capacity <= (
      SELECT count(*) FROM ticket_resources hr JOIN tickets h ON h.id = hr.ticket_id
      WHERE h.status = 'in_progress' AND h.id <> t.id AND hr.rkey = r.rkey))
  -- A provider resource needs a ready slot (#407).
  AND NOT EXISTS (
    SELECT 1 FROM ticket_resources r
    JOIN resource_providers p ON p.name = r.rkey
    WHERE r.ticket_id = t.id
      AND NOT EXISTS (SELECT 1 FROM resource_slots s WHERE s.pool = p.name AND s.state = 'ready'))
ORDER BY t.priority, t.created_at, t.id
LIMIT CAST(? AS INTEGER)
`

