const writeTicket = `-- name: WriteTicket :execrows
UPDATE tickets SET
  title       = ?1,
  body        = ?2,
  status      = ?3,
  resolution  = ?4,
  priority    = ?5,
  pool        = ?6,
  holder      = ?7,
  lease_until = ?8,
  fence       = ?9,
  defer_until = ?10,
  fields      = ?11,
  f_key       = ?12,
  f_to        = ?13,
  f_state     = ?14,
  f_workflow  = ?15,
  f_index     = ?16,
  f_waiting   = ?17,
  meta        = ?18,
  revision    = ?19,
  updated_at  = ?20,
  closed_at   = ?21
WHERE id = ?22 AND revision = ?23
`

type WriteTicketParams struct {
	Title            string
	Body             string
	Status           string
	Resolution       string
	Priority         int64
	Pool             string
	Holder           string
	LeaseUntil       int64
	Fence            int64
	DeferUntil       int64
	Fields           string
	FKey             sql.NullString
	FTo              sql.NullString
	FState           sql.NullString
	FWorkflow        sql.NullString
	FIndex           sql.NullInt64
	FWaiting         int64
	Meta             string
	Revision         int64
	UpdatedAt        int64
	ClosedAt         int64
	ID               string
	ExpectedRevision int64
}

// WriteTicket stores every mutable column, guarded by the previous revision.
func (q *Queries) WriteTicket(ctx context.Context, arg WriteTicketParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, writeTicket,
		arg.Title,
		arg.Body,
		arg.Status,
		arg.Resolution,
		arg.Priority,
		arg.Pool,
		arg.Holder,
		arg.LeaseUntil,
		arg.Fence,
		arg.DeferUntil,
		arg.Fields,
		arg.FKey,
		arg.FTo,
		arg.FState,
		arg.FWorkflow,
		arg.FIndex,
		arg.FWaiting,
		arg.Meta,
		arg.Revision,
		arg.UpdatedAt,
		arg.ClosedAt,
		arg.ID,
		arg.ExpectedRevision,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
